def rich_table(path):
 table(path);files={};dirs={}
 with tarfile.open(path,'r:')as t:
  for m in t:
   n=m.name.rstrip('/');v={'mode':m.mode,'uid':m.uid,'gid':m.gid}
   if m.isdir():dirs[n]=v
   else:files[n]={**v,'bytes':m.size,'sha256':sha(t.extractfile(m).read())}
 return {'files':files,'directories':dirs}

